import itertools, json, sys, os
from problems import VertexCover, DominatingSet
import importlib.util, importlib.machinery
spec = importlib.util.spec_from_file_location('reduce', 'reduce.py')
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)
reduce = mod.reduce

def vc_bruteforce(inst):
    n=inst['n']; edges=inst['edges']; k=inst['k']
    if k<0: return False
    verts=range(n)
    for r in range(k+1):
        for subset in itertools.combinations(verts,r):
            s=set(subset)
            if all(u in s or v in s for u,v in edges):
                return True
    return False

def ds_bruteforce(inst):
    n=inst['n']; edges=inst['edges']; k=inst['k']
    if k<0: return False
    adj=[set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    verts=range(n)
    for r in range(k+1):
        for subset in itertools.combinations(verts,r):
            D=set(subset)
            ok=True
            for v in verts:
                if v not in D and not (adj[v] & D):
                    ok=False; break
            if ok:
                return True
    return False

def random_instance(max_n=5):
    import random
    n=random.randint(0,max_n)
    possible=[(i,j) for i in range(n) for j in range(i+1,n)]
    edges=[]
    for (i,j) in possible:
        if random.random()<0.4:
            edges.append([i,j])
    k=random.randint(-1, n+2)
    return {'n':n,'edges':edges,'k':k}

for _ in range(2000):
    src=random_instance()
    try:
        VertexCover.validate(src)
    except Exception as e:
        print('invalid src',src)
        raise
    ans_src=vc_bruteforce(src)
    tgt=reduce(src)
    try:
        DominatingSet.validate(tgt)
    except Exception as e:
        print('invalid tgt',tgt)
        raise
    ans_tgt=ds_bruteforce(tgt)
    if ans_src!=ans_tgt:
        print('Mismatch!')
        print('src',src,'ans',ans_src)
        print('tgt',tgt,'ans',ans_tgt)
        sys.exit(0)
print('All ok')
